insert into public.page_sections(page_slug,key,name,source_collection,position,visible,data_draft,published_position,published_visible,data_published) values ('inicio','ciencia','Ciencia y técnica FUE',null,4,true,'{"content": {"es": {"t1": "Precisión médica.", "t2": "Resultados diseñados para ti.", "text": "Cómo funciona la técnica FUE: extracción, preparación e implantación.", "cta": "Contáctanos", "ctaLink": "https://wa.me/19548535335"}, "en": {}}, "lists": {"beneficios": {"head": "Beneficios junto al video", "noun": "beneficio", "fields": [{"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}], "fixed": false, "items": [{"visible": true, "es": {"t": "Anestesia local con bloqueos nerviosos", "d": "La menor cantidad posible de anestesia, para mayor comodidad."}, "en": {}}, {"visible": true, "es": {"t": "Sin cicatriz lineal", "d": "La extracción es puntual, folículo a folículo."}, "en": {}}, {"visible": true, "es": {"t": "Recuperación inicial de 7–10 días", "d": "Con indicaciones claras y seguimiento."}, "en": {}}, {"visible": true, "es": {"t": "Diseño natural", "d": "Ángulo, dirección y densidad de tu propio cabello."}, "en": {}}]}, "pasos": {"head": "Puntos interactivos de la técnica FUE", "noun": "punto", "fields": [{"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}], "fixed": false, "items": [{"visible": true, "es": {"t": "Extracción", "d": "Se extraen unidades foliculares una a una desde la zona donante, habitualmente la nuca, con microinstrumental. [Revisar con especialistas]"}, "en": {}}, {"visible": true, "es": {"t": "Preparación", "d": "Las unidades se seleccionan y conservan mientras se diseña la zona receptora según tu línea natural. [Revisar con especialistas]"}, "en": {}}, {"visible": true, "es": {"t": "Implantación", "d": "Cada unidad se coloca respetando ángulo, dirección y densidad de tu propio cabello. [Revisar con especialistas]"}, "en"