insert into public.page_sections(page_slug,key,name,source_collection,position,visible,data_draft,published_position,published_visible,data_published) values ('inicio','proceso','El proceso en 5 etapas',null,5,true,'{"content": {"es": {"t1": "Tu transformación comienza", "t2": "con una conversación.", "text": "El proceso Dr Follicle en 5 etapas."}, "en": {}}, "lists": {"etapas": {"head": "Etapas del proceso", "noun": "etapa", "fields": [{"key": "t", "label": "Título de la etapa", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}, {"key": "m", "label": "Etiquetas (separadas por coma)", "multiline": false}], "fixed": false, "items": [{"visible": true, "es": {"t": "Valoración gratis", "d": "Hablamos de tu caso por videollamada o en la clínica: tus expectativas, tu historial y lo que te gustaría cambiar. La primera valoración no tiene costo.", "m": "Sin costo, Presencial o virtual"}, "en": {}}, {"visible": true, "es": {"t": "Diagnóstico capilar", "d": "Evaluamos la causa de la caída, la zona donante disponible, las características de tu cabello y cómo ha progresado la caída. Así definimos qué es posible en tu caso y diseñamos tu línea frontal.", "m": "Zona donante, Diseño de línea frontal"}, "en": {}}, {"visible": true, "es": {"t": "Plan de tratamiento personalizado", "d": "Recibes un plan por escrito: técnica recomendada, estimación de unidades foliculares, tiempos y cuidados, para que decidas con calma.", "m": "Plan por escrito, Diseño de línea frontal"}, "en": {}}, {"visible": true, "es": {"t": "Procedimiento", "d": "Se realiza con técnica FUE y anestesia local en Medellín. Te explicamos la duración estimada según tu plan y te acompañamos durante toda la jornada.", "m": "Técnica FUE, Anestesia local"}, "en": {}}, {"visible": true, "es": {"t": "Seguimiento y recuperación", "d": "La recuperación inicial suele tomar de 7 a 10 días. Los primeros signos de crecimiento aparecen entre el tercer y cuarto mes, y el resultado completo entre los 8 y 12 meses.", "m": "Kit postoperatorio, Controles a distancia"}, "en": {}}]}}, "slots": [{"label": "Etapa 1 · Valoración", "kind": "img", "src": "images/team-cut.png", "alt": {"es": "Equipo de Dr Follicle Solutions", "en": ""}}, {"label": "Etapa 2 · Diagnóstico", "kind": "img", "src": "images/diagnostico.jpg", "alt": {"es": "Especialista preparando a un paciente con la nueva línea frontal marcada", "en": ""}}, {"label": "Etapa 3 · Plan", "kind": "img", "src": "images/proc-a.jpg", "alt": {"es": "Diseño de la línea frontal con el paciente", "en": ""}}, {"label": "Etapa 4 · Procedimiento", "kind": "img", "src": "images/surgery-team.jpg", "alt": {"es": "Cirujano y asistente durante la extracción", "en": ""}}, {"label": "Etapa 5 · Seguimiento", "kind": "img", "src": "images/res-3-resultado.webp", "alt": {"es": "Resultado de un paciente meses después de su trasplante", "en": ""}}]}'::jsonb,5,true,'{"content": {"es": {"t1": "Tu transformación comienza", "t2": "con una conversación.", "text": "El proceso Dr Follicle en 5 etapas."}, "en": {}}, "lists": {"etapas": {"head": "Etapas del proceso", "noun": "etapa", "fields": [{"key": "t", "label": "Título de la etapa", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}, {"key": "m", "label": "Etiquetas (separadas por coma)", "multiline": false}], "fixed": false, "items": [{"visible": true, "es": {"t": "Valoración gratis", "d": "Hablamos de tu caso por videollamada o en la clínica: tus expectativas, tu historial y lo que te gustaría cambiar. La primera valoración no tiene costo.", "m": "Sin costo, Presencial o virtual"}, "en": {}}, {"visible": true, "es": {"t": "Diagnóstico capilar", "d": "Evaluamos la causa de la caída, la zona donante disponible, las características de tu cabello y cómo ha progresado la caída. Así definimos qué es posible en tu caso y diseñamos tu línea frontal.", "m": "Zona donante, Diseño de línea frontal"}, "en": {}}, {"visible": true, "es": {"t": "Plan de tratamiento personalizado", "d