insert into public.page_sections(page_slug,key,name,source_collection,position,visible,data_draft,published_position,published_visible,data_published) values ('inicio','turismo','Turismo médico',null,7,true,'{"content": {"es": {"t1": "Tu tratamiento capilar en Medellín,", "t2": "con acompañamiento en cada etapa.", "text": "Vengas de donde vengas, coordinamos contigo cada paso para que solo te ocupes de tu recuperación y de disfrutar Medellín.", "cta": "Conoce nuestra experiencia para pacientes internacionales", "ctaLink": "/turismo-medico"}, "en": {"t1": "Your hair transplant in Medellín,", "t2": "with support at every step.", "text": "Wherever you are coming from, we coordinate every step so you can focus on your recovery and enjoy Medellín.", "cta": "Discover our international patient experience", "ctaLink": "/en/medical-tourism"}}, "lists": {"lista": {"head": "Lo que incluye el acompañamiento", "noun": "elemento", "fields": [{"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}], "fixed": false, "items": [{"visible": true, "es": {"t": "Evaluación previa a distancia", "d": "Videollamada con el equipo antes de comprar tu vuelo."}, "en": {}}, {"visible": true, "es": {"t": "Orientación para organizar el viaje", "d": "Fechas recomendadas, documentos y tiempo de estadía sugerido."}, "en": {}}, {"visible": true, "es": {"t": "Coordinación del procedimiento", "d": "Exámenes preoperatorios, consulta médica y cirugía en la misma agenda."}, "en": {}}, {"visible": true, "es": {"t": "Alojamiento y traslados", "d": "Recogida en el aeropuerto, gestión del hotel y acompañamiento personalizado durante tu estadía."}, "en": {}}, {"visible": true, "es": {"t": "Tours por Medellín con nosotros", "d": "Programa recorridos por la ciudad con nuestro equipo y vive un turismo médico premium, a tu medida."}, "en": {}}, {"visible": true, "es": {"t": "Indicaciones postoperatorias", "d": "Kit postoperatorio y guía de cuidados para los primeros días."}, "en": {}}, {"visible": true, "es": {"t": "Seguimiento desde tu país", "d": "Controles a distancia mientras crece tu nuevo cabello."}, "en": {}}]}}, "slots": [{"label": "Foto 1 · Metro de Medellín", "kind": "img", "src": "images/medellin.jpg", "alt": {"es": "El metro de Medellín atravesando el centro de la ciudad", "en": ""}}, {"label": "Foto 2 · Lugar turístico", "kind": "img", "src": "", "alt": {"es": "", "en": ""}, "note": "Pendiente"}, {"label": "Foto 3 · Lugar turístico", "kind": "img", "src": "", "alt": {"es": "", "en": ""}, "note": "Pendiente"}, {"label": "Foto 4 · Lugar turístico", "kind": "img", "src": "", "alt": {"es": "", "en": ""}, "note": "Pendiente"}, {"label": "Foto 5 · Lugar turístico", "kind": "img", "src": "", "alt": {"es": "", "en": ""}, "note": "Pendiente"}]}'::jsonb,7,true,'{"content": {"es": {"t1": "Tu tratamiento capilar en Medellín,", "t2": "con acompañamiento en cada etapa.", "text": "Vengas de donde vengas, coordinamos contigo cada paso para que solo te ocupes de tu recuperación y de disfrutar Medellín.", "cta": "Conoce nuestra experiencia para pacientes internacionales", "ctaLink": "/turismo-medico"}, "en": {"t1": "Your hair transplant in Medellín,", "t2": "with support at every step.", "text": "Wherever you are coming from, we coordinate every step so you can focus on your recovery and enjoy Medellín.", "cta": "Discover our international patient experience", "ctaLink": "/en/medical-tourism"}}, "lists": {"lista": {"head": "Lo que incluye el acompañamiento", "noun": "elemento", "fields": [{"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}], "fixed": false, "items": [{"visible": true, "es": {"t": "Evaluación previa a distancia", "d": "Videollamada con el equipo antes de comprar tu vuelo."}, "en": {}}, {"visible": true, "es": {"t": "Orientación para organizar el viaje", "d": "Fechas recomendadas, documentos y tiempo de estadía sugerido."}, "en": {}}, {"visible": true, "es":