pa del proceso."}, "en": {}}, {"visible": true, "es": {"t": "Seguimiento dedicado", "d": "Controles a largo plazo, también a distancia."}, "en": {}}]}}, "slots": [{"label": "Foto de la técnica", "kind": "img", "src": "images/surgery-team.jpg", "alt": {"es": "Cirujano y asistente durante una extracción FUE", "en": ""}}]}'::jsonb);
insert into public.page_sections(page_slug,key,name,source_collection,position,visible,data_draft,published_position,published_visible,data_published) values ('nosotros','compromisos','Por qué nos eligen',null,4,true,'{"content": {"es": {"t1": "Experiencia, transparencia", "t2": "y cercanía.", "text": "Tu comodidad, tu seguridad y tu confianza son nuestra prioridad."}, "en": {}}, "lists": {"items": {"head": "Compromisos", "noun": "compromiso", "fields": [{"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}], "fixed": false, "items": [{"visible": true, "es": {"t": "Solo fotos reales, con autorización", "d": "Publicamos resultados de pacientes reales con su autorización escrita."}, "en": {}}, {"visible": true, "es": {"t": "Sin promesas imposibles", "d": "Te explicamos con honestidad qué es posible en tu caso; los resultados varían según cada paciente."}, "en": {}}, {"visible": true, "es": {"t": "Tu plan por escrito", "d": "Técnica, tiempos y cuidados, para que decidas con calma."}, "en": {}}, {"visible": true, "es": {"t": "Experiencia para pacientes internacionales", "d": "Consulta previa a distancia, coordinación del viaje y seguimiento postoperatorio desde tu país."}, "en": {}}]}}}'::jsonb,4,true,'{"content": {"es": {"t1": "Experiencia, transparencia", "t2": "y cercanía.", "text": "Tu comodidad, tu seguridad y tu confianza son nuestra prioridad."}, "en": {}}, "lists": {"items": {"head": "Compromisos", "noun": "compromiso", "fields": [{"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}], "fixed": false, "items": [{"visible": true, "es": {"t": "Solo fotos reales, con autorización", "d": "Publicamos resultados de pacientes reales con su autorización escrita."}, "en": {}}, {"visible": true, "es": {"t": "Sin promesas imposibles", "d": "Te explicamos con honestidad qué es posible en tu caso; los resultados varían según cada paciente."}, "en": {}}, {"visible": t