insert into public.page_sections(page_slug,key,name,source_collection,position,visible,data_draft,published_position,published_visible,data_published) values ('nosotros','largoplazo','Resultados a largo plazo',null,5,true,'{"content": {"es": {"t1": "Resultados pensados", "t2": "a largo plazo.", "text": "La restauración capilar es una transformación gradual: los tratamientos están pensados para un crecimiento sostenible y una densidad equilibrada. Los tiempos varían según cada paciente."}, "en": {}}, "lists": {"tiempos": {"head": "Línea de tiempo", "noun": "hito", "fields": [{"key": "m", "label": "Cuándo", "multiline": false}, {"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}], "fixed": false, "items": [{"visible": true, "es": {"m": "7–10 días", "t": "Recuperación inicial", "d": "Enrojecimiento e hinchazón leves son esperables."}, "en": {}}, {"visible": true, "es": {"m": "3–4 meses", "t": "Primeros signos de crecimiento", "d": "Empieza a aparecer el nuevo cabello."}, "en": {}}, {"visible": true, "es": {"m": "4–6 meses", "t": "Mejora visible", "d": "La densidad se nota cada vez más."}, "en": {}}, {"visible": true, "es": {"m": "8–12 meses", "t": "Resultado final", "d": "La recuperación completa puede tomar entre 6 y 12 meses."}, "en": {}}]}, "nota": {"head": "Nota bajo la línea de tiempo", "noun": "nota", "fields": [{"key": "d", "label": "Texto", "multiline": true}], "fixed": true, "items": [{"visible": true, "es": {"d": "Evita la actividad física intensa durante al menos 2 semanas y sigue las indicaciones del médico. Te damos instrucciones detalladas y acompañamiento continuo. [Revisar con especialistas]"}, "en": {}}]}}}'::jsonb,5,true,'{"content": {"es": {"t1": "Resultados pensados", "t2": "a largo plazo.", "text": "La restauración capilar es una transformación gradual: los tratamientos están pensados para un crecimiento sostenible y una densidad equilibrada. Los tiempos varían según cada paciente."}, "en": {}}, "lists": {"tiempos": {"head": "Línea de tiempo", "noun": "hito", "fields": [{"key": "m", "label": "Cuándo", "multiline": false}, {"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}], "fixed": false, "items": [{"visible": true, "es": {"m": "7–10 días", "t": "Recuperación inicial", "d": "Enrojecimiento e hinchazón leves son esperables."}, "en": {}}, {"visible": true, "es": {"m": "3–4 meses", "t": "Primeros signos de crecimiento", "d": "Empieza a aparecer el nuevo cabello."}, "en": {}}, {"visible": true, "es": {"m": "4–6 meses", "t": "Mejora visible", "d": "La densidad se nota cada vez más."}, "en": {}}, {"visible": true, "es": {"m": "8–12 meses", "t": "Resultado final", "d": "La recuperación completa puede tomar entre 6 y 12 meses."}, "en": {}}]}, "nota": {"head": "Nota bajo la línea de tiempo", "noun": "nota", "fields": [{"key": "d", "label": "Texto", "multiline": true}], "fixed": true, "items": [{"visible": true, "es": {"d": "Evita la actividad física intensa durante al menos 2 semanas y sigue las indicaciones del médico. Te damos instrucciones detalladas y acompañamiento continuo. [Revisar con especialistas]"}, "en": {}}]}}}'::jsonb);
