insert into public.page_sections(page_slug,key,name,source_collection,position,visible,data_draft,published_position,published_visible,data_published) values ('turismo-medico','viaje','Tu viaje paso a paso',null,1,true,'{"content": {"es": {"t1": "Tu viaje,", "t2": "paso a paso.", "text": "Evaluación a distancia · Organización del viaje · Alojamiento y traslados · Tours por Medellín · Procedimiento · Recuperación · Seguimiento desde tu país"}, "en": {}}, "lists": {"etapas": {"head": "Etapas del viaje", "noun": "etapa", "fields": [{"key": "m", "label": "Momento", "multiline": false}, {"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}, {"key": "w", "label": "Lo que hacemos nosotros", "multiline": false}, {"key": "u", "label": "Lo que haces tú", "multiline": false}], "fixed": false, "items": [{"visible": true, "es": {"m": "Antes de viajar", "t": "Evaluación previa a distancia", "d": "Hablamos por videollamada antes de que compres tu vuelo, para conocer tu caso y definir si eres candidato.", "w": "Revisamos tu caso y te proponemos un plan.", "u": "Nos compartes tu historial y tus expectativas."}, "en": {}}, {"visible": true, "es": {"m": "Antes de viajar", "t": "Orientación para organizar el viaje", "d": "Te recomendamos fechas, los documentos que necesitas y el tiempo de estadía sugerido para tu plan.", "w": "Te enviamos una guía para tu viaje.", "u": "Compras tu vuelo en las fechas acordadas."}, "en": {}}, {"visible": true, "es": {"m": "Al llegar", "t": "Alojamiento y traslados", "d": "Te recogemos en el aeropuerto, gestionamos tu hotel y te acompañamos de forma personalizada durante tu estadía.", "w": "Recogida en el aeropuerto y gestión del hotel.", "u": "Nos compartes tu itinerario de vuelo."}, "en": {}}, {"visible": true, "es": {"m": "Durante tu estadía", "t": "Tours por Medellín con nosotros", "d": "Programa recorridos por la ciudad con nuestro equipo y vive un turismo médico premium, a tu medida.", "w": "Armamos contigo tu agenda de tours.", "u": "Nos cuentas qué te gustaría conocer."}, "en": {}}, {"visible": true, "es": {"m": "En la clínica", "t": "Coordinación del procedimiento", "d": "Exámenes preoperatorios, consulta médica y cirugía en la misma agenda, para aprovechar tu tiempo en Medellín.", "w": "Organizamos toda tu agenda médica.", "u": "Sigues las indicaciones previas a la cirugía."}, "en": {}}, {"visible": true, "es": {"m": "Recuperación", "t": "Indicaciones postoperatorias", "d": "Recibes tu kit postoperatorio y una guía de cuidados para los primeros días, antes de volver a casa.", "w": "Kit postoperatorio y controles en la clínica.", "u": "Descansas y sigues la guía de cuidados."}, "en": {}}, {"visible": true, "es": {"m": "De vuelta en casa", "t": "Seguimiento desde tu país", "d": "Hacemos controles a distancia mientras crece tu nuevo cabello, hasta ver el resultado final.", "w": "Controles a distancia y resolución de dudas.", "u": "Nos envías fotos de tu evolución."}, "en": {}}]}}, "slots": [{"label": "Etapa 1 · Evaluación", "kind": "img", "src": "images/team-cut.png", "alt": {"es": "Equipo de Dr Follicle Solutions", "en": ""}}, {"label": "Etapa 2 · Orientación", "kind": "img", "src": "images/medellin.jpg", "alt": {"es": "Medellín", "en": ""}}, {"label": "Etapa 3 · Al llegar", "kind": "img", "src": "images/medellin.jpg", "alt": {"es": "Medellín", "en": ""}}, {"label": "Etapa 4 · Tours", "kind": "img", "src": "images/medellin.jpg", "alt": {"es": "Medellín", "en": ""}}, {"label": "Etapa 5 · Clínica", "kind": "img", "src": "images/surgery-team.jpg", "alt": {"es": "Cirujano y asistente durante una extracción FUE", "en": ""}}, {"label": "Etapa 6 · Recuperación", "kind": "img", "src": "images/diagnostico.jpg", "alt": {"es": "Especialista con un paciente", "en": ""}}, {"label": "Etapa 7 · De vuelta en casa", "kind": "img", "src": "images/res-3-resultado.webp", "alt": {"es": "Resultado de un paciente", "en": ""}}]}'::jsonb,1,true,'{"content": {"es": {"t1": "Tu viaje,", "t2": "paso a paso.", "text": "Evaluación a distancia · Organización del viaje · Alojamiento y traslados · Tours por Medellín · Procedimiento · Recuperación · Seguimiento desde tu país"}, "en": {}}, "lists": {"etapas": {"head": "Etapas del viaje", "noun": "etapa", "fields": [{"key": "m", "label": "Momento", "multiline": false}, {"key": "t", "label": "Título", "multiline": false}, {"key": "d", "label": "Descripción", "multiline": true}, {"key": "w", "label": "Lo que hacemos nosotros", "multiline": false}, {"key": "u", "label": "Lo que haces tú", "multiline": false}], "fixed": false, "items": [{"visible": true, "es": {"m": "Antes de viajar", "t": "Evaluación previa a distancia", "d": "Hablamos por videollamada antes de que compres tu vuelo, para conocer tu caso y definir si eres candidato.", "w": "Revisamos tu caso y te proponemos un plan.", "u": "Nos compartes tu historial y tus expectativas."}, "en": {}}, {"visible": true, "es": {"m": "Antes de viajar", "t": "Orientación para organizar el viaje", "d": "Te recomendamos fechas, los documentos que necesitas y el tiempo de estadía sugerido para tu plan.", "w": "Te enviamos una guía para tu viaje.", "u": "Compras tu vuelo en las fechas acordadas."}, "en": {}}, {"visible": true, "es": {"m": "Al llegar", "t": "Alojamiento y traslados", "d": "Te recogemos en el aeropuerto, gestionamos tu hotel y te acompañamos de forma personalizada durante tu estadía.", "w": "Recogida en el aeropuerto y gestión del hotel.", "u": "Nos compartes tu itinerario de vuelo."}, "en": {}}, {"visible": true, "es": {"m": "Durante tu estadía", "t": "Tours por Medellín con nosotros", "d": "Programa recorridos por la ciudad con nuestro equipo y vive un turismo médico premium, a tu medida.", "w": "Armamos contigo tu agenda de tours.", "u": "Nos cuentas qué te gustaría conocer."}, "en": {}}, {"visible": true, "es": {"m": "En la clínica", "t": "Coordinación del procedimiento", "d": "Exámenes preoperatorios, consulta médica y cirugía en la misma agen