insert into public.testimonials(position,author,country,treatment,quote,source_note,authorization_confirmed,visible) values (1,'Tatiana Ortega','[País]','Trasplante capilar','{"es": "Se encargaron de cada detalle, desde un transporte confiable hasta el alojamiento. El trato del doctor y del equipo me hizo sentir tranquila de principio a fin.", "en": ""}'::jsonb,'Reseña publicada en drfolliclesolutions.com, traducida del inglés',false,true);
insert into public.testimonials(position,author,country,treatment,quote,source_note,authorization_confirmed,visible) values (2,'Daniella G.','[País]','Acompañante de paciente','{"es": "Mi prometido siempre se sintió inseguro con su línea frontal. A los seis meses de la operación ya vemos una gran diferencia, y nos cuidaron en cada momento.", "en": ""}'::jsonb,'Reseña publicada en drfolliclesolutions.com, traducida del inglés',false,true);
insert into public.testimonials(position,author,country,treatment,quote,source_note,authorization_confirmed,visible) values (3,'John E.','[País]','Trasplante capilar','{"es": "Desde la consulta inicial hasta los resultados finales, todo el proceso fue fluido. Estoy encantado con lo natural que se ve.", "en": ""}'::jsonb,'Reseña publicada en drfolliclesolutions.com, traducida del inglés',false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (0,array['inicio']::text[],'{"es": "¿Duele el procedimiento?", "en": ""}'::jsonb,'{"es": "Depende de la tolerancia de cada persona. La anestesia local puede arder al aplicarse; por eso el especialista prefiere bloqueos nerviosos, que usan la menor cantidad posible de anestesia y dan mayor comodidad. Nuestros pacientes lo describen como incómodo, más que doloroso.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (1,array['inicio']::text[],'{"es": "¿Cuánto dura un trasplante capilar?", "en": ""}'::jsonb,'{"es": "Está pensado para dar resultados duraderos, a menudo permanentes, porque los folículos trasplantados suelen ser resistentes al patrón de caída. Cada paciente es diferente: los cuidados y los controles médicos son clave para el mejor resultado a largo plazo.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (2,array['inicio']::text[],'{"es": "¿Cómo funciona un trasplante capilar?", "en": ""}'::jsonb,'{"es": "Se trasladan unidades foliculares desde una zona donante, normalmente la nuca, hacia las zonas con menor densidad. En Dr Follicle Solutions se realiza con técnica FUE y anestesia local.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (3,array['inicio']::text[],'{"es": "¿Quién puede ser candidato?", "en": ""}'::jsonb,'{"es": "Cada caso de caída es distinto. En la valoración evaluamos la causa de la caída, la zona donante disponible, las características de tu cabello y la progresión de la caída.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (4,array['inicio']::text[],'{"es": "¿Qué diferencia existe entre las técnicas disponibles?", "en": ""}'::jsonb,'{"es": "[Respuesta por definir con los especialistas, según las técnicas que ofrece la clínica.]", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (5,array['inicio']::text[],'{"es": "¿Cómo es la recuperación?", "en": ""}'::jsonb,'{"es": "La recuperación inicial suele tomar entre 7 y 10 días, con enrojecimiento e inflamación leves. Se recomienda evitar actividad física intensa durante al menos dos semanas.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (6,array['inicio']::text[],'{"es": "¿Cuándo suelen observarse resultados?", "en": ""}'::jsonb,'{"es": "Los primeros signos de crecimiento suelen aparecer entre el tercer y el cuarto mes. El resultado completo se observa, en general, entre los 8 y los 12 meses.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (7,array['inicio']::text[],'{"es": "¿Qué incluye una valoración?", "en": ""}'::jsonb,'{"es": "Una conversación sobre tu caso, la revisión de tu historial y expectativas, y una propuesta de plan. La primera valoración no tiene costo.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (8,array['inicio']::text[],'{"es": "¿Puedo viajar desde otro país para realizarme el procedimiento?", "en": ""}'::jsonb,'{"es": "Sí. Hacemos la valoración a distancia, te orientamos para organizar el viaje y te acompañamos en el seguimiento desde tu país.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (9,array['trasplante-capilar','trasplante-de-barba']::text[],'{"es": "¿Duele el procedimiento?", "en": ""}'::jsonb,'{"es": "Depende de la tolerancia de cada persona. El especialista prefiere bloqueos nerviosos, que usan la menor cantidad posible de anestesia y dan mayor comodidad. Nuestros pacientes lo describen como incómodo, más que doloroso.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (10,array['trasplante-capilar']::text[],'{"es": "¿Cuánto dura la recuperación completa?", "en": ""}'::jsonb,'{"es": "La recuperación inicial toma entre 7 y 10 días, con enrojecimiento e inflamación leves. La recuperación completa y la aparición del nuevo cabello toman entre 6 y 12 meses.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (11,array['trasplante-capilar']::text[],'{"es": "¿Puedo hacer actividad física después?", "en": ""}'::jsonb,'{"es": "Evita la actividad intensa durante al menos dos semanas. Puedes retomar la actividad ligera de forma gradual, siguiendo las indicaciones del especialista.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (12,array['trasplante-capilar']::text[],'{"es": "¿Cuándo veré resultados?", "en": ""}'::jsonb,'{"es": "El crecimiento suele empezar entre el tercer y el cuarto mes. El resultado final se observa entre los 8 y los 12 meses.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (13,array['trasplante-capilar']::text[],'{"es": "¿Quién puede ser candidato?", "en": ""}'::jsonb,'{"es": "Lo definimos en la valoración: evaluamos la causa de la caída, la zona donante disponible, las características de tu cabello y su progresión.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (14,array['trasplante-de-barba']::text[],'{"es": "¿De dónde se toman los folículos?", "en": ""}'::jsonb,'{"es": "De la zona occipital del cuero cabelludo, en la nuca.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (15,array['trasplante-de-barba']::text[],'{"es": "¿El resultado es permanente?", "en": ""}'::jsonb,'{"es": "Sí. Está pensado como un resultado permanente y natural.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (16,array['trasplante-de-barba']::text[],'{"es": "¿Cuándo puedo volver a mi rutina?", "en": ""}'::jsonb,'{"es": "En pocos días, siguiendo las indicaciones del especialista.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (17,array['trasplante-de-barba']::text[],'{"es": "¿Sirve para cubrir cicatrices?", "en": ""}'::jsonb,'{"es": "Sí. También se usa para cubrir cicatrices y mejorar la densidad en zonas despobladas.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (18,array['trasplante-de-cejas']::text[],'{"es": "¿Cuánto dura el procedimiento?", "en": ""}'::jsonb,'{"es": "Aproximadamente de 3 a 4 horas, con anestesia local.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (19,array['trasplante-de-cejas']::text[],'{"es": "¿De dónde se toman los folículos?", "en": ""}'::jsonb,'{"es": "Del cuero cabelludo, con técnica FUE.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (20,array['trasplante-de-cejas']::text[],'{"es": "¿El resultado se ve natural?", "en": ""}'::jsonb,'{"es": "Sí. Los folículos se colocan siguiendo la dirección natural de tus cejas.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (21,array['trasplante-de-cejas']::text[],'{"es": "¿Es un procedimiento seguro?", "en": ""}'::jsonb,'{"es": "Es un procedimiento seguro y bien tolerado, con una recuperación rápida.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (22,array['terapias-capilares']::text[],'{"es": "¿Para quién es el plasma capilar?", "en": ""}'::jsonb,'{"es": "Para quienes empiezan a notar la caída o quieren proteger su cabello, y como complemento de un trasplante.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (23,array['terapias-capilares']::text[],'{"es": "¿Necesito cirugía?", "en": ""}'::jsonb,'{"es": "No. Es una terapia no quirúrgica.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (24,array['terapias-capilares']::text[],'{"es": "¿Cuántas sesiones necesito?", "en": ""}'::jsonb,'{"es": "[Respuesta por confirmar con la clínica, según cada caso.]", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (25,array['turismo-medico']::text[],'{"es": "¿Puedo hacer la valoración sin viajar?", "en": ""}'::jsonb,'{"es": "Sí. La primera valoración es a distancia y no tiene costo. Así sabes si eres candidato antes de comprar tu vuelo.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (26,array['turismo-medico']::text[],'{"es": "¿Cuántos días debo quedarme en Medellín?", "en": ""}'::jsonb,'{"es": "[Respuesta por confirmar con la clínica: tiempo de estadía sugerido según el tratamiento.]", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (27,array['turismo-medico']::text[],'{"es": "¿Me recogen en el aeropuerto?", "en": ""}'::jsonb,'{"es": "Sí. Coordinamos la recogida en el aeropuerto y te ayudamos a gestionar tu hotel.", "en": ""}'::jsonb,false,true);
insert into public.faqs(position,scopes,question,answer,medical_review_done,visible) values (28,array['turismo-medico']::text[],'{"es": "¿Cómo es el seguimiento cuando regreso?", "en": ""}'::jsonb,'{"es": "Hacemos controles a distancia mientras crece tu nuevo cabello. El resultado final se observa entre los 8 y los 12 meses.", "en": ""}'::jsonb,false,true);
